 if(argc>1){Session h(image);TestBacking test;auto backend=test.Backend();const std::u16string package=u"TEST.prefs";std::string mode=argv[1];auto adapter=std::make_unique<AndroidSharedPreferences>(h.host,h.context,package,backend);if(mode=="--expired"){adapter.reset();h.open(package);}else if(mode=="--store")h.open(u"unknown");else if(mode=="--mode"){auto name=h.string(package);h.run("prefs_open_mode",{h.env(),h.context,name,1});}else if(mode=="--context"){auto foreign=h.host.NewInstance("android/app/Activity"),name=h.string(package);h.run("prefs_open",{h.env(),foreign,name,0});}else if(mode=="--failure"){test.fail=true;auto p=h.open(package),e=h.edit(p);h.put(e,u"a",1,2);h.apply(e);adapter->CheckPersistence();}throw std::runtime_error("expected SharedPreferences boundary returned");}
 bool namespace_rejected=false;try{MakeWindowsSharedPreferencesBackend(u"test.Foo");}catch(const std::runtime_error&e){namespace_rejected=std::string(e.what()).find("lowercase profile required")!=std::string::npos;}Check(namespace_rejected,"case-insensitive registry cannot alias two accepted package identities");
